  $j$[{"kind": "n8n workflow", "name": "ORACLE_DEBATE_V1 moMxiV4Irg1uRBZN, nodes QR Merge, QR Follow Build and QR Follow Final (qfCheck)", "before": "version ebf1dbcf; a follow-up passes when its open words stand word for word in the question or its passage", "after": "version 8470161f-f72a-4719-835d-1ae4e245ed56; a follow-up whose open words equal the whole question (case, spacing, quote marks and trailing punctuation set aside) is faulted and DROPPED with its reply recorded; tagged ASK 645"}]$j$::jsonb,
  $j$[{"name": "t645.cjs on the build", "result": "24 pass, 0 fail: C1 the 24 stored follow-up checks (one changes, 42528 sol62's of Q2, PASSED to DROPPED); C2 the whole question in other case, without \"?\", with \".\" is dropped, a part or the passage passes; C3 the three qfCheck texts are equal, only 3 nodes change, connections equal; C4 tag, no catch, no dead code", "source": "Wall 12058; reproduced by W1, Wall 12062, 12072, 12076"}, {"name": "Standing set with child aad0ad9c", "result": "31 PASS, 0 FAIL on the target (W4, W1), on the fetch-back (W4, Wall 12075) and on live (W1, Wall 12076); pair Library Check PASSES; reg385 PASS", "source": "Wall 12058, 12069, 12072, 12075, 12076"}, {"name": "NOT RUN", "result": "any live call", "source": "Wall 12075"}]$j$::jsonb,
  $j$[{"seat": "W1", "result": "PASS (638 A and 645 read back together: W1's own build of 638 A then 645 on 393bca2e equals live 8470161f in all 426 nodes and the connections; t645 24 pass 0 fail; standing 31 PASS 0 FAIL). NOT CHECKED: audit rows.", "wall_id": 12076, "source": "Wall 12076 (commit c68f090c)"}]$j$::jsonb,
  $j${"case": "NO RUN YET.", "runs": [], "mark_for_the_next_run": "on the first run in which a judge's follow-up gives the whole question as its open words: the follow-up is DROPPED with the fault \"the open words are the whole of Q<n>\" and no answer call is made for it; a follow-up naming a part passes as before.", "not_shown": "the fault on a live question round.", "source": "Wall 12058, 12075"}$j$::jsonb,
  $j${"op_doc": "none", "engine_manual": "WRITTEN: part 14.0 version 331 (md5 1f513052a353442dfc010a9031718166, 8,197 characters, log row 351), on the operator's press \"Write all six\" at 09:08 CST 2026-11-25 on W3's card (cmsg_017ZQamDMHrS6fqMHnQDVo589AHY4EW5dD8Zdyt26PvafU); audit 42303; pairs graded PASS by W1 (Wall 12121); read back PASS by W1 (Wall 12129)."}$j$::jsonb,
